{
  "case_id": "C03",
  "audience": "School governors and parents",
  "target_duration_s": 60,
  "beats": [
    {
      "beat": "Why absence matters",
      "narration": "Respiratory illness is the single biggest driver of pupil absence in our primary schools, accounting for roughly half of coded absence days across the winter.",
      "on_screen": "Title: Air cleaners and pupil absence. Pie graphic: about half of winter absence days coded respiratory.",
      "claim_refs": ["Background"]
    },
    {
      "beat": "What was tried",
      "narration": "Twenty-two classrooms in one local authority were each given two portable HEPA air cleaners, running during school hours. Eighteen classrooms in the same authority carried on as usual. Absence was tracked for one eleven-week winter term.",
      "on_screen": "Split graphic: 22 classrooms with two HEPA units each, versus 18 classrooms without. Caption: 11-week winter term.",
      "claim_refs": ["Abstract", "Methods"]
    },
    {
      "beat": "What the numbers showed",
      "narration": "In classrooms with units, respiratory absence fell from four point nine to three point six percent of pupil-days. In the comparison classrooms it fell only slightly, from four point seven to four point four. The difference works out at about one percentage point, though the plausible range runs from just under two points down to almost nothing.",
      "on_screen": "Bar chart of before and after for both groups. Callout: difference of -1.0 percentage points, 95% confidence interval -1.9 to -0.1.",
      "claim_refs": ["Results", "Abstract"]
    },
    {
      "beat": "How much weight to give it",
      "narration": "This was not a randomised trial. Schools chose which rooms got units based on available floor space, staff could see which rooms had them, ventilation already differed between the two groups, and absence came from an administrative code rather than any test for infection. It covers one term in one authority.",
      "on_screen": "Checklist of caveats: not randomised, rooms chosen by floor space, unblinded, ventilation differed at baseline, coded absence not confirmed infection, single term and authority.",
      "claim_refs": ["Study design", "Methods", "Limitations"]
    },
    {
      "beat": "What it means for governors",
      "narration": "A one point reduction would be operationally meaningful across a large authority, so the finding is worth taking seriously. But governors should weigh purchase and running costs against a result this uncertain, and any wider rollout deserves proper evaluation.",
      "on_screen": "Two columns: potential benefit versus unit and running costs. Closing line: promising, not proven; evaluate before wider rollout.",
      "claim_refs": ["Discussion", "Conclusion"]
    }
  ]
}
